INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(131928, 'ruRU', '', 'Он внутри дерева, да? Тогда идём за ним. Его время пришло!', 24330),
(131929, 'ruRU', '', 'Мы можем пойти прямо к этому личу, $n. Если он действительно организует это нападение, то его смерть должна рассеять их силы.', 24330),
(131930, 'ruRU', '', 'Вот и ещё одна угроза устранена, да ещё и своевременно!', 24330),
(131932, 'ruRU', '', 'Хм? Что это? Какой-то хроноосколок? Мне нужно отнести его обратно в Крыло Вирмов, чтобы изучить.', 24330),
(131933, 'ruRU', '', 'Он говорит справедливо. Давай пороемся в этой жуткой пещере в поисках подсказок.', 24330),
(131934, 'ruRU', '', 'Дредлорд? И бронзовый дракон... Погоди, это он про меня говорит?', 24330),
(131935, 'ruRU', '', 'И похоже, он выдал своё местоположение. Ха! Идём к входу в Обсидиановое святилище драконов и прикончим его!', 24330),
(131936, 'ruRU', '', 'К счастью для нас, мы уже знаем о дредлорде-организаторе, дёргающем за ниточки. Убьём его, прежде чем он убьёт меня!', 24330),
(131937, 'ruRU', '', 'Хм! Интересно, что Легиону нужно от такой малышки, как я.', 24330),
(131938, 'ruRU', '', 'Хм... хроноосколок. Давай отнесём это обратно в Крыло Вирмов. Интересно, куда и когда он ведёт.', 24330),
(131940, 'ruRU', '', 'Мы можем помочь с этим!', 24330),
(131941, 'ruRU', '', 'Мы можем помочь с этим, да?', 24330),
(131942, 'ruRU', '', 'Сновидцы дали нам три подсказки... великий кошмар, у воды, ладонь дракона. Нам просто нужно понять, что они значат.', 24330),
(131943, 'ruRU', '', 'Идём!', 24330),
(131944, 'ruRU', '', 'Помни, сатир внизу, в той костяной расщелине у воды. Прикончим его!', 24330),
(131945, 'ruRU', '', 'Странно. Не помню, чтобы ссорилась с сатирами ни сейчас, НИ в будущем.', 24330),
(131946, 'ruRU', '', 'Глянь-ка! Хроноосколок. Нам нужно взять его с собой в Крыло Вирмов.', 24330),
(131947, 'ruRU', '', 'Давай спустимся туда и поищем подсказки. Может, возмущения исходят от того, кто хочет меня убить.', 24330),
(131948, 'ruRU', '', 'Пропустим силовые линии и пойдём прямо к этому повелителю пустоты. Время не ждёт!', 24330),
(131949, 'ruRU', '', 'Вот уж не ожидала, что окажусь во врагах у ПОВЕЛИТЕЛЯ ПУСТОТЫ, ну надо же. Фух.', 24330),
(131950, 'ruRU', '', 'А ну-ка глянь сюда... у него был хроноосколок. Мне нужно отнести его в Крыло Вирмов, чтобы узнать, куда он ведёт.', 24330),
(131951, 'ruRU', '', 'У меня появляется подозрение, что враг планирует кросс-синхронное нападение. Иначе зачем бы они использовали хроноосколки, да?', 24330),
(131952, 'ruRU', '', 'Вижу, тебе не совсем ясно, что это значит. По сути, они атакуют меня в нескольких точках времени одновременно.', 24330),
(131953, 'ruRU', '', 'Эти ребята действительно знают, что делают! Не удивлюсь, если на их стороне есть бронзовый дракон.', 24330),
(131954, 'ruRU', '', 'Интересно... портал в Андорал. Это одно из моих любимых мест в любое когда! Посмотрим, не в беде ли я.', 24330),
(131955, 'ruRU', '', 'Ага! Портал на гору Хиджал. Я бывала там раз, два, ДЕРЕВО. ТРИ. Я хотела сказать три.', 24330),
(131956, 'ruRU', '', 'Вижу... портал в Стратхольм, во времена Третьей войны.', 24330),
(131957, 'ruRU', '', 'Ого... старенький, но добрый! Этот портал ведёт к Колодцу Вечности.', 24330),
(131958, 'ruRU', '', 'Андорал, несколько месяцев после Катаклизма. Мы в самой гуще битвы между Ордой и Альянсом.', 24330),
(131960, 'ruRU', '', 'Вот одна из проблем быть гномом. Иногда у солдат Орды просто возникает порыв тебя ПИНАТЬ.', 24330),
(131962, 'ruRU', '', 'АЛЬЯНС тоже хочет меня? Да что вообще происходит?', 24330),
(131963, 'ruRU', '', 'Здесь я могу держаться сама, но не могу улететь, пока эта пушка направлена в небо.', 24330),
(131964, 'ruRU', '', 'Пушка уничтожена. Ты сможешь выбраться?', 24330),
(131965, 'ruRU', '', 'Думаю, да. Увидимся следующий раз!', 24330),
(131966, 'ruRU', '', 'Стратхольм, во времена Третьей войны. Я помню этот день. Не самый лучший момент принца Артаса.', 24330),
(131969, 'ruRU', '', 'Похоже, мы направляемся в Стратхольм! Поторопимся, у нас мало времени!', 24330),
(131970, 'ruRU', '', 'Ох! Какое мерзкое на вид создание. Ну, мимо неё не пройти. Похоже, придётся с ней сразиться.', 24330),
(131971, 'ruRU', '', 'Огромное спасибо, что спасла меня, я!', 24330),
(131972, 'ruRU', '', 'В любое время!', 24330),
(131973, 'ruRU', '', 'Так, посмотрим... мы на горе Хиджал, вскоре после времён Катаклизма.', 24330);
